# ----- BEGIN entry script: encode_main.pl -----
{
our $PROGRAM_NAME;
our $VERSION;
use strict;
use warnings;
# bundled: use PCWAV::Common;
# bundled: use PCWAV::WavWriter;
# bundled: use PCWAV::Binary::S1Encode;
# bundled: use PCWAV::Basic::S1Encode;
# bundled: use PCWAV::Basic::S2Encode;
# bundled: use PCWAV::Binary::OldEncode;
# bundled: use PCWAV::Basic::OldEncode;
PCWAV::TextCodec->import(qw(preprocess_escape));
use Encode qw(decode);
use utf8;

sub prog_name {
    return $PROGRAM_NAME
        || do {
            require File::Basename;
            File::Basename::basename($0);
        };
}

sub usage {
    my $prog = prog_name();
    die <<"MSG";
usage:
  perl $prog s1bin    input.bin output.wav [filename] [addr]
  perl $prog s1basic  input.bas output.wav [filename]
  perl $prog s2basic  input.bas output.wav [filename]
  perl $prog oldbin   input.bin output.wav [filename] [addr]
  perl $prog oldbasic input.bas output.wav [filename]
MSG
}

sub show_banner {
    my $name = prog_name();
    my $ver = defined $VERSION ? $VERSION : 'dev';

    print "$name version $ver\n";
}

sub encode_s1bin {
    my ($input, $output, $filename, $addr) = @_;

    $filename = defined $filename ? $filename : '';
    $addr     = defined $addr ? PCWAV::Common::parse_num($addr) : 0xC000;

    my $bin   = PCWAV::Common::read_file_bin($input);
    my @bytes = PCWAV::Common::bytes_from_scalar($bin);

    my @payload = PCWAV::Binary::S1Encode::build_payload(
        addr  => $addr,
        name  => $filename,
        bytes => \@bytes,
    );

    my $pcm = PCWAV::Binary::S1Encode::payload_to_pcm(@payload);
    PCWAV::WavWriter::write_wav_file($output, $pcm);
    print "wrote $output\n";
}

sub encode_s1basic {
    my ($input, $output, $filename) = @_;

    $filename = defined $filename ? $filename : '';

    my $text = PCWAV::Common::read_file_bin($input);
    $text = decode('UTF-8', $text);
    $text = preprocess_escape($text);
    my $payload = PCWAV::Basic::S1Encode::encode_s1_basic_text($text, $filename);
    my @payload_bytes = PCWAV::Common::bytes_from_scalar($payload);
    # S1/S2 BASIC: real machines emit/expect an extra trailing FF byte
    # after the logical terminator FF FF SUM. This is treated as a physical
    # stream trailer, not as part of the BASIC payload.
    push @payload_bytes, 0xFF;
    my $pcm = PCWAV::Binary::S1Encode::payload_to_pcm(@payload_bytes);
    PCWAV::WavWriter::write_wav_file($output, $pcm);
    print "wrote $output\n";
}

sub encode_s2basic {
    my ($input, $output, $filename, $type) = @_;
    $filename = defined $filename ? $filename : '';

    my $type_num = defined $type ? PCWAV::Common::parse_num($type) : 0x27;

    my $text = PCWAV::Common::read_file_bin($input);
    $text = decode('UTF-8', $text);
    $text = preprocess_escape($text);
    my $payload = PCWAV::Basic::S2Encode::encode_s2_basic_text($text, $filename, $type_num);

    my @payload_bytes = PCWAV::Common::bytes_from_scalar($payload);
    # S1/S2 BASIC: real machines emit/expect an extra trailing FF byte
    # after the logical terminator FF FF SUM. This is treated as a physical
    # stream trailer, not as part of the BASIC payload.
    push @payload_bytes, 0xFF;
    my $pcm = PCWAV::Binary::S1Encode::payload_to_pcm(@payload_bytes);
    PCWAV::WavWriter::write_wav_file($output, $pcm);
    print "wrote $output\n";
}

sub encode_oldbin {
    my ($input, $output, $filename, $addr) = @_;

    $filename = defined $filename ? $filename : '';
    $addr     = defined $addr ? PCWAV::Common::parse_num($addr) : 0xC000;

    my $bin   = PCWAV::Common::read_file_bin($input);
    my @bytes = PCWAV::Common::bytes_from_scalar($bin);

    my $payload = PCWAV::Binary::OldEncode::encode_payload(
        filename   => $filename,
        start_addr => $addr,
        body       => \@bytes,
    );
    my @payload_bytes = PCWAV::Common::bytes_from_scalar($payload);

    my $pcm = PCWAV::Binary::OldEncode::payload_to_pcm(@payload_bytes);
    PCWAV::WavWriter::write_wav_file($output, $pcm);
    print "wrote $output\n";
}

sub encode_oldbasic {
    my ($input, $output, $filename) = @_;

    $filename = defined $filename ? $filename : '';

    my $text = PCWAV::Common::read_file_bin($input);
    $text = preprocess_escape($text);
    my $payload = PCWAV::Basic::OldEncode::encode_payload(
        text     => $text,
        filename => $filename,
        password => 0,
    );
    my @payload_bytes = PCWAV::Common::bytes_from_scalar($payload);

    my $pcm = PCWAV::Binary::OldEncode::payload_to_pcm(@payload_bytes);
    PCWAV::WavWriter::write_wav_file($output, $pcm);
    print "wrote $output\n";
}

sub main {
    show_banner();
    my @args = @ARGV;
    usage() unless @args >= 3;

    my $mode = shift @args;

    if    ($mode eq 's1bin')    { usage() unless @args >= 2; encode_s1bin(@args); }
    elsif ($mode eq 's1basic')  { usage() unless @args >= 2; encode_s1basic(@args); }
    elsif ($mode eq 's2basic')  { usage() unless @args >= 2; encode_s2basic(@args); }
    elsif ($mode eq 'oldbin')   { usage() unless @args >= 2; encode_oldbin(@args); }
    elsif ($mode eq 'oldbasic') { usage() unless @args >= 2; encode_oldbasic(@args); }
    else {
        die "unknown mode: $mode\n";
    }
}

main();
}
# ----- END entry script: encode_main.pl -----
